CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- ── daily_shop_reports ────────────────────────────────────────
-- Pre-aggregated daily stats per shop — used by report-service
-- for fast dashboard queries without cross-DB joins
CREATE TABLE daily_shop_reports (
    id              UUID          PRIMARY KEY DEFAULT gen_random_uuid(),
    shop_id         VARCHAR(100)  NOT NULL,
    report_date     DATE          NOT NULL,
    total_orders    INTEGER       DEFAULT 0,
    completed_orders INTEGER      DEFAULT 0,
    cancelled_orders INTEGER      DEFAULT 0,
    total_revenue   DECIMAL(12,2) DEFAULT 0,
    online_revenue  DECIMAL(12,2) DEFAULT 0,
    cash_revenue    DECIMAL(12,2) DEFAULT 0,
    avg_order_value DECIMAL(10,2) DEFAULT 0,
    new_customers   INTEGER       DEFAULT 0,
    repeat_customers INTEGER      DEFAULT 0,
    peak_hour       INTEGER,
    top_item        VARCHAR(255),
    created_at      TIMESTAMP     DEFAULT NOW(),
    UNIQUE (shop_id, report_date)
);

CREATE INDEX idx_daily_shop      ON daily_shop_reports (shop_id);
CREATE INDEX idx_daily_date      ON daily_shop_reports (report_date DESC);
CREATE INDEX idx_daily_shop_date ON daily_shop_reports (shop_id, report_date DESC);

-- ── hourly_shop_reports ───────────────────────────────────────
CREATE TABLE hourly_shop_reports (
    id           UUID          PRIMARY KEY DEFAULT gen_random_uuid(),
    shop_id      VARCHAR(100)  NOT NULL,
    report_date  DATE          NOT NULL,
    hour_of_day  SMALLINT      NOT NULL CHECK (hour_of_day BETWEEN 0 AND 23),
    order_count  INTEGER       DEFAULT 0,
    revenue      DECIMAL(12,2) DEFAULT 0,
    UNIQUE (shop_id, report_date, hour_of_day)
);

CREATE INDEX idx_hourly_shop_date ON hourly_shop_reports (shop_id, report_date DESC);

-- ── top_items_reports ─────────────────────────────────────────
CREATE TABLE top_items_reports (
    id           UUID          PRIMARY KEY DEFAULT gen_random_uuid(),
    shop_id      VARCHAR(100)  NOT NULL,
    report_date  DATE          NOT NULL,
    menu_item_id VARCHAR(100)  NOT NULL,
    item_name    VARCHAR(255)  NOT NULL,
    qty_sold     INTEGER       DEFAULT 0,
    revenue      DECIMAL(12,2) DEFAULT 0,
    rank         SMALLINT,
    UNIQUE (shop_id, report_date, menu_item_id)
);

CREATE INDEX idx_top_items_shop_date ON top_items_reports (shop_id, report_date DESC);
CREATE INDEX idx_top_items_rank      ON top_items_reports (shop_id, report_date, rank);

-- ── platform_daily_reports ────────────────────────────────────
CREATE TABLE platform_daily_reports (
    id               UUID          PRIMARY KEY DEFAULT gen_random_uuid(),
    report_date      DATE          NOT NULL UNIQUE,
    total_shops      INTEGER       DEFAULT 0,
    active_shops     INTEGER       DEFAULT 0,
    new_shops        INTEGER       DEFAULT 0,
    total_orders     INTEGER       DEFAULT 0,
    total_revenue    DECIMAL(15,2) DEFAULT 0,
    total_users      INTEGER       DEFAULT 0,
    new_users        INTEGER       DEFAULT 0,
    total_hotels     INTEGER       DEFAULT 0,
    total_malls      INTEGER       DEFAULT 0,
    qr_scans         INTEGER       DEFAULT 0,
    support_tickets  INTEGER       DEFAULT 0,
    created_at       TIMESTAMP     DEFAULT NOW()
);

CREATE INDEX idx_platform_date ON platform_daily_reports (report_date DESC);

-- ── customer_activity ─────────────────────────────────────────
CREATE TABLE customer_activity (
    id             UUID          PRIMARY KEY DEFAULT gen_random_uuid(),
    customer_id    VARCHAR(100),
    customer_name  VARCHAR(255),
    shop_id        VARCHAR(100)  NOT NULL,
    activity_date  DATE          NOT NULL,
    order_count    INTEGER       DEFAULT 0,
    total_spent    DECIMAL(12,2) DEFAULT 0,
    last_order_at  TIMESTAMP,
    UNIQUE (customer_id, shop_id, activity_date)
);

CREATE INDEX idx_cust_activity_shop   ON customer_activity (shop_id, activity_date DESC);
CREATE INDEX idx_cust_activity_cust   ON customer_activity (customer_id);

-- ── report_jobs ───────────────────────────────────────────────
-- Track async report generation jobs
CREATE TABLE report_jobs (
    id          UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    shop_id     VARCHAR(100),
    type        VARCHAR(50)  NOT NULL,
    status      VARCHAR(20)  DEFAULT 'PENDING',
    date_from   DATE,
    date_to     DATE,
    result_url  VARCHAR(1000),
    error_msg   TEXT,
    requested_by VARCHAR(100),
    created_at  TIMESTAMP    DEFAULT NOW(),
    completed_at TIMESTAMP
);

CREATE INDEX idx_report_jobs_shop   ON report_jobs (shop_id);
CREATE INDEX idx_report_jobs_status ON report_jobs (status);

CREATE SEQUENCE seq_report_job START 1001 INCREMENT 1;

